footer_layout.css:
footer {
    background-color: var(--vm-footer-bg) !important;
    color: var(--vm-footer-text) !important;
    border-top: 1px solid var(--vm-border);
}
footer a { color: var(--vm-footer-text); opacity: 0.8; }
footer a:hover { color: var(--vm-primary); opacity: 1; }

quickedit_remocao.css:
.quickedit,
.widget-item-control,
.item-control,
.item-control.blog-admin {
    display: none !important;
    height: 0 !important;
    width: 0 !important;
    opacity: 0 !important;
    visibility: hidden !important;
}
#navbar-iframe { display: none !important; }
